spec.query:
count(
  count by (user) (
    (
      (
        sum by (user, subscription, limitador_namespace) (
          increase(authorized_calls{user!="", user=~"$user", subscription=~"$subscription"}[$__range])
        )
        +
        sum by (user, subscription, limitador_namespace) (
          increase(limited_calls{user!="", user=~"$user", subscription=~"$subscription"}[$__range])
        )
      )
      or
      sum by (user, subscription, limitador_namespace) (
        increase(authorized_calls{user!="", user=~"$user", subscription=~"$subscription"}[$__range])
      )
    )
    * on(user, subscription, limitador_namespace)
    (0 * (max by (user, subscription, limitador_namespace) (max_over_time(authorized_hits{model=~"$model"}[$__range])) or max by (user, subscription, limitador_namespace) (max_over_time((label_replace(authorized_calls{limitador_namespace=~"[^/]*/($model)"}, "model", "$1", "limitador_namespace", "[^/]*/(.*)") unless on(user, subscription, limitador_namespace) authorized_hits)[$__range:]))) + 1)
    > 0
  )
) or vector(0)

(
  (
    sum(
      sum by (user, subscription, limitador_namespace) (
        increase(authorized_calls{user!="", user=~"$user", subscription=~"$subscription"}[$__range])
      )
      * on(user, subscription, limitador_namespace)
      (0 * (max by (user, subscription, limitador_namespace) (max_over_time(authorized_hits{model=~"$model"}[$__range])) or max by (user, subscription, limitador_namespace) (max_over_time((label_replace(authorized_calls{limitador_namespace=~"[^/]*/($model)"}, "model", "$1", "limitador_namespace", "[^/]*/(.*)") unless on(user, subscription, limitador_namespace) authorized_hits)[$__range:]))) + 1)
    )
  )
  /
  (
    (
      sum(
        sum by (user, subscription, limitador_namespace) (
          increase(authorized_calls{user!="", user=~"$user", subscription=~"$subscription"}[$__range])
        )
        * on(user, subscription, limitador_namespace)
        (0 * (max by (user, subscription, limitador_namespace) (max_over_time(authorized_hits{model=~"$model"}[$__range])) or max by (user, subscription, limitador_namespace) (max_over_time((label_replace(authorized_calls{limitador_namespace=~"[^/]*/($model)"}, "model", "$1", "limitador_namespace", "[^/]*/(.*)") unless on(user, subscription, limitador_namespace) authorized_hits)[$__range:]))) + 1)
      )
      +
      (
        sum(
          sum by (user, subscription, limitador_namespace) (
            increase(limited_calls{user!="", user=~"$user", subscription=~"$subscription"}[$__range])
          )
          * on(user, subscription, limitador_namespace)
          (0 * (max by (user, subscription, limitador_namespace) (max_over_time(authorized_hits{model=~"$model"}[$__range])) or max by (user, subscription, limitador_namespace) (max_over_time((label_replace(authorized_calls{limitador_namespace=~"[^/]*/($model)"}, "model", "$1", "limitador_namespace", "[^/]*/(.*)") unless on(user, subscription, limitador_namespace) authorized_hits)[$__range:]))) + 1)
        )
        or vector(0)
      )
    ) > 0
  )
) or vector(1)
